-- GPT Image 2.5 Flare and Sunburst, the two GPT Image 2.5 editors of Fash's Image Generation menu, on fal. Both share GPT Image 2's input schema
-- (packages/core/src/providers/fal.ts sends the same body) and its token prices ($8 input / $30 output per 1M image tokens, model pages read 2026-10-26),
-- so they carry GPT Image 2's 1K price at the high quality tier and its six preset ratios; the schema allows up to 16 images, the app keeps GPT Image 2's 4.
-- No public leaderboard lists them yet, so they start without a prior. They are added disabled; an Admin enables them (audited).
INSERT INTO "model_configs" ("id", "provider", "endpoint", "label", "kind", "features", "ratios", "durations_sec", "max_images", "image_prices", "sources") VALUES
